import{_ as t,o,c as a,a2 as n}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"RFC 0087 — Sovereign Relay: native push notifications and WebRTC signaling","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign/blob/main/docs/rfcs/0087-sovereign-relay.md"},"headers":[],"relativePath":"rfcs/0087-sovereign-relay.md","filePath":"rfcs/0087-sovereign-relay.md"}'),i={name:"rfcs/0087-sovereign-relay.md"};function s(r,e,d,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="rfc-0087-—-sovereign-relay-native-push-notifications-and-webrtc-signaling" tabindex="-1">RFC 0087 — Sovereign Relay: native push notifications and WebRTC signaling <a class="header-anchor" href="#rfc-0087-—-sovereign-relay-native-push-notifications-and-webrtc-signaling" aria-label="Permalink to &quot;RFC 0087 — Sovereign Relay: native push notifications and WebRTC signaling&quot;">​</a></h1><p><strong>Status:</strong> Implemented<br><strong>Date:</strong> August 2026<br><strong>Author:</strong> Claude Code (design discussion with <code>kasunben</code>)<br><strong>Scope:</strong> <code>packages/db</code> (new device-token schema), <code>runtime</code> (registration API, extends RFC 0015/0016&#39;s fan-out, relay-URL configuration), a new standalone service <code>apps/relay</code> (this monorepo), <code>sovereign-mobile</code> (external repo — client registration, encryption, native decrypt-and-display; tracked there via that repo&#39;s own epic 20 task 20.5), <code>sovereign-desktop</code> (external repo, per the &quot;Desktop native push&quot; addendum below — client registration, encryption, native decrypt-and-display; tracked there via this monorepo&#39;s own epic 17 task 17.11), the <code>sovereign-infra</code> / <code>openfs-infra</code> deployment repositories (external — relay deployment playbook)<br><strong>Incorporated into plan:</strong> Yes — epic task 4.7 (this monorepo) and epic task 20.5, rescoped (<code>sovereign-mobile</code>&#39;s client-side half); epic tasks 4.8 and 17.11 (the desktop addendum). Sequenced by <a href="./../workstreams/0005-native-push-relay.html">workstream 0005</a> for the mobile push feature and <a href="./../workstreams/0010-desktop-push-relay.html">workstream 0010</a> for the desktop addendum; WebRTC signaling&#39;s own implementation is intentionally not sequenced yet (see &quot;Feature: WebRTC signaling&quot; below).</p><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>This RFC introduces <strong>Sovereign Relay</strong> (<code>apps/relay</code>): one small piece of <code>sovereignfs</code>-operated infrastructure, shared by every feature that needs a neutral, centrally-reachable rendezvous point but must not be able to read what it relays. It starts with two independent features:</p><ol><li><strong>Native mobile push notifications</strong> (APNs for iOS, FCM for Android) — the fully-designed feature this RFC originally covered, unchanged in substance. APNs/FCM require credentials tied to one app identity, and <code>sovereign-mobile</code> is one published app used by many independent self-hosted instances that cannot each hold that credential — so a relay is structurally required, not just convenient. Content-blind by design (Nextcloud&#39;s proven pattern): every self-hosted instance encrypts the notification payload against the recipient device&#39;s own public key before it ever leaves the instance, so the relay only ever forwards an opaque blob it cannot read.</li><li><strong>WebRTC signaling</strong> (offer/answer/ICE candidate exchange) — a much lighter feature, design-sketched only, for future real-time peer-to-peer capabilities (the first planned consumer is a decentralized chat app, not designed here — see &quot;Feature: WebRTC signaling&quot; below). Two peers behind NATs need a reachable third party to exchange connection metadata before they can talk directly; unlike push, this has no app-identity credential binding, so it is structurally easier to self-host.</li></ol><p>Both features — and any relay-shaped feature added later — share one deployable app, one deployment story, and one operator opt-out/self-host path, rather than each reinventing its own. See &quot;Deployment topology&quot; for why this is a genuinely different kind of service from every other app in this monorepo (<code>runtime</code>, <code>apps/auth</code>): it is not something every self-hosted operator deploys, so it does not belong in the default <code>docker-compose.yml</code>/<code>docker-compose.prod.yml</code> stack.</p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p><code>sovereign-mobile</code> task 20.5 has existed as a roadmap line item without a real design: &quot;add native push&quot; was scoped as if it were a Capacitor integration task dependent only on RFC 0015/0016. It isn&#39;t — see <a href="./../research/0010-native-mobile-push-notifications.html">Research 0010</a> for the full investigation, including confirmation (from Apple&#39;s own DTS engineers and Chromium&#39;s issue tracker) that Web Push is platform-blocked inside a WKWebView/WebView embedded in a third-party app, and research into how Nextcloud, Matrix/Element, Home Assistant, and Bitwarden — all comparable self-hosted or federated products — solved the identical problem. Without this RFC, the native mobile app can never notify a user once the app is closed; PWA and browser-tab users are unaffected either way since Web Push already works for them.</p><p>While designing push&#39;s deployment story, it became clear the same shape of problem — a self-hosted instance needs a centrally-reachable, content-blind intermediary it doesn&#39;t fully trust with plaintext — will recur. The clearest near-term case is WebRTC signaling: two devices, each behind a NAT neither controls, need a reachable rendezvous point to exchange connection offers before they can attempt a direct peer-to-peer connection. This RFC generalizes the relay concept now, while only push&#39;s feature-level design is final, so the second feature doesn&#39;t have to re-litigate the deployment question push already answered.</p><p>This ties directly to Sovereign&#39;s self-hosted, privacy-first positioning: every other device capability (RFC 0083&#39;s <code>haptics.impact</code>, <code>notifications.native</code>, <code>secureStorage</code>) is architected so the shell talks only to the user&#39;s own instance and the OS, never to a <code>sovereignfs</code>-run server. Native push is the first capability that cannot honor that pattern completely — Apple/Google&#39;s push transport requires a credentialed sender in the loop by design — so this RFC&#39;s central design goal is minimizing what that sender can see, not just making push work. WebRTC signaling doesn&#39;t share push&#39;s credential constraint, but benefits from the same minimize-what-the-relay-can-see discipline and the same deployment machinery.</p><h2 id="current-state-what-this-builds-on" tabindex="-1">Current state (what this builds on) <a class="header-anchor" href="#current-state-what-this-builds-on" aria-label="Permalink to &quot;Current state (what this builds on)&quot;">​</a></h2><ul><li><strong>RFC 0015 (Notification Center)</strong> and <strong>RFC 0016 (Web Push)</strong> are both Implemented. The delivery fan-out lives in <code>runtime/src/push.ts</code>: <code>fanOutPushToUser(userId, payload)</code> fetches every registered subscription for a user (<code>getPushSubscriptionsForUser</code>) and delivers to each independently via <code>Promise.allSettled</code>, pruning subscriptions the push service reports as gone (<code>runtime/src/push.ts:89–163</code>). This RFC adds a second delivery branch to the same function; it does not restructure it.</li><li><strong><code>push_subscriptions</code></strong> (<code>packages/db/src/schema/{sqlite,postgres}/platform.ts</code>) stores the Web Push <code>PushSubscription</code> shape (<code>endpoint</code>, <code>p256dh</code>, <code>auth</code>) — structurally incompatible with an APNs/FCM device token, which needs a different shape (see below).</li><li><strong>RFC 0083 (device bridge, Draft)</strong> shipped <code>notifications.native</code> in workstream 0003 (legs 3/4) — a foreground-only, locally-triggered capability (<code>sdk.device.nativeNotifications.show()</code>), unrelated to this RFC&#39;s server-initiated delivery except that the native app <strong>reuses it to display</strong> a push once decrypted (see &quot;Client-side flow&quot; below).</li><li><strong><code>apps/auth</code></strong> is this monorepo&#39;s only precedent for a standalone deployable app outside the main <code>runtime</code> Next.js app — a minimal Next.js service with its own <code>package.json</code>, <code>Dockerfile</code>, and <code>scripts/next-server.mjs</code>-driven dev/start scripts. <code>apps/relay</code> follows the same code-structure shape (see &quot;Shared relay platform&quot; below) — but, critically, <strong>not</strong> <code>apps/auth</code>&#39;s deployment shape. <code>apps/auth</code> is a per-instance service every operator deploys; <code>apps/relay</code> is a shared, centrally-operated service almost no operator deploys themselves. See &quot;Deployment topology.&quot;</li><li><strong><code>sovereign-mobile</code></strong> already has a <code>notificationPermissionLauncher</code>-style runtime-permission flow (Android <code>POST_NOTIFICATIONS</code>, iOS <code>UNUserNotificationCenter</code>) from workstream 0003 leg 4 — this RFC&#39;s client-side permission handling extends the same pattern rather than introducing a new one.</li><li><strong><code>sovereign-infra</code></strong> (public, forkable template) and <strong><code>openfs-infra</code></strong> (private, <code>sovereignfs</code>&#39;s own production deployment) are the two operator-facing deployment repositories, external to this monorepo. Both already document an &quot;Adding a New App&quot; playbook (per-app <code>docker-compose.yml</code><ul><li>Caddy vhost + encrypted <code>.env</code>, deployed independently of the special-cased <code>sovereign</code> app whose compose is fetched from this monorepo&#39;s own releases) — <code>apps/relay</code> is deployed as exactly that kind of app, not as part of the <code>sovereign</code> app&#39;s stack. See &quot;Deployment topology.&quot;</li></ul></li></ul><h2 id="proposed-design" tabindex="-1">Proposed design <a class="header-anchor" href="#proposed-design" aria-label="Permalink to &quot;Proposed design&quot;">​</a></h2><h3 id="shared-relay-platform-apps-relay" tabindex="-1">Shared relay platform (<code>apps/relay</code>) <a class="header-anchor" href="#shared-relay-platform-apps-relay" aria-label="Permalink to &quot;Shared relay platform (\`apps/relay\`)&quot;">​</a></h3><p>A new, minimal, mostly-stateless Next.js app, following <code>apps/auth</code>&#39;s existing <em>code</em> precedent (own <code>package.json</code>, <code>Dockerfile</code>, <code>scripts/next-server.mjs</code> dev/start scripts) rather than introducing a new framework or deployment pattern to this monorepo. Its own deployment <em>topology</em> is different from <code>apps/auth</code>&#39;s — see &quot;Deployment topology.&quot;</p><p>Design principles that apply to every feature hosted here, not just push:</p><ul><li><strong>Content-blind wherever technically possible.</strong> The relay forwards opaque, already-encrypted payloads (push) or short-lived connection metadata that is useless without the peer completing a direct connection (signaling). It should never be the thing holding a plaintext notification, a message, or a call&#39;s actual media/data.</li><li><strong>Minimal, revocable per-instance authentication.</strong> Each self-hosted instance obtains a lightweight API key from the relay at enrollment (<code>POST /v1/enroll</code>, one-time, before first use) and includes it on every relay call. This is deliberately minimal — not a full OAuth flow — since the credential being protected is &quot;ability to use this relay,&quot; not user data; its job is basic abuse prevention (rate-limiting per instance, revocable if an instance misbehaves), not strong authorization. One enrollment covers every feature the instance uses on the relay — an instance doesn&#39;t re-enroll per feature.</li><li><strong>No persistent state beyond what a feature strictly needs to function.</strong> Push needs none (pure forward). Signaling needs a short-TTL session record (see below), not a durable one. Neither needs logging of the content it relays.</li><li><strong>Small surface area.</strong> The smaller this service&#39;s surface, the smaller the blast radius if it&#39;s ever compromised — it should hold exactly the credentials/state each feature strictly requires (push: Apple/Firebase credentials) and nothing else sensitive.</li></ul><h3 id="feature-push-notifications" tabindex="-1">Feature: Push notifications <a class="header-anchor" href="#feature-push-notifications" aria-label="Permalink to &quot;Feature: Push notifications&quot;">​</a></h3><p>The fully-designed feature. Unchanged from this RFC&#39;s original scope.</p><h4 id="device-token-schema" tabindex="-1">Device-token schema <a class="header-anchor" href="#device-token-schema" aria-label="Permalink to &quot;Device-token schema&quot;">​</a></h4><p>New table, dialect-agnostic (SQLite + Postgres, per this repo&#39;s hard rule), alongside <code>push_subscriptions</code> in <code>packages/db/src/schema/{sqlite,postgres}/platform.ts</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>push_device_tokens</span></span>
<span class="line"><span>  id              text/uuid primary key</span></span>
<span class="line"><span>  user_id         references users.id, cascade delete</span></span>
<span class="line"><span>  platform        &#39;ios&#39; | &#39;android&#39;</span></span>
<span class="line"><span>  device_token    text — the raw APNs device token or FCM registration token</span></span>
<span class="line"><span>  public_key      text — base64-encoded device public key (encryption target)</span></span>
<span class="line"><span>  relay_url       text — the relay this token was registered against (see below)</span></span>
<span class="line"><span>  created_at      timestamp</span></span>
<span class="line"><span>  last_used_at    timestamp, nullable — updated on successful delivery</span></span></code></pre></div><p><code>relay_url</code> is stored per-token, not read from a single instance-wide setting at send time — an operator can change their configured relay after a device has already registered, and old tokens must keep resolving to the relay they actually registered with until the device re-registers.</p><h4 id="client-side-flow" tabindex="-1">Client-side flow <a class="header-anchor" href="#client-side-flow" aria-label="Permalink to &quot;Client-side flow&quot;">​</a></h4><p>Detailed further in <code>sovereign-mobile</code>&#39;s own epic task 20.5.</p><ol><li>On first enabling push, the app generates an encryption keypair on-device (native <code>CryptoKit</code> on iOS, Android&#39;s <code>KeyStore</code>-backed equivalent — not exportable, private key never leaves the device).</li><li><code>@capacitor/push-notifications</code> registers with APNs/FCM as normal, yielding a device token.</li><li>The app sends <code>{platform, deviceToken, publicKey}</code> to its <strong>own</strong> instance&#39;s new registration endpoint (below) — the relay URL used is whatever that instance is currently configured with.</li><li>On receipt of a push, native platform code (an iOS <strong>Notification Service Extension</strong> — required to run code before the OS displays a banner; Android&#39;s FCM background handling needs no separate extension) decrypts the payload with the stored private key and populates the notification content, reusing the <code>notifications.native</code> display path from workstream 0003.</li><li>Sign-out or instance removal calls the revocation endpoint, deleting the <code>push_device_tokens</code> row; a token the relay reports as invalid (device uninstalled the app) is pruned the same way <code>push_subscriptions</code> already is on a 410/404.</li></ol><h4 id="server-side-registration-api-and-fan-out-extension-runtime" tabindex="-1">Server-side: registration API and fan-out extension (<code>runtime</code>) <a class="header-anchor" href="#server-side-registration-api-and-fan-out-extension-runtime" aria-label="Permalink to &quot;Server-side: registration API and fan-out extension (\`runtime\`)&quot;">​</a></h4><ul><li><code>POST /api/account/push-device-token</code> — registers <code>{platform, deviceToken, publicKey}</code> for the current session&#39;s user, storing the instance&#39;s currently configured relay URL alongside it. Mirrors <code>/api/account/push-subscription</code>&#39;s existing shape and auth handling.</li><li><code>DELETE /api/account/push-device-token/:id</code> — revokes one token (sign-out, instance removal, or explicit opt-out).</li><li><code>fanOutPushToUser</code> (<code>runtime/src/push.ts</code>) gains a second branch: for each row in <code>push_device_tokens</code> for the recipient, encrypt <code>payload</code> against <code>public_key</code> (see &quot;Encryption&quot; below) and POST the result to <code>relay_url</code>. Both branches run inside the same <code>Promise.allSettled</code> fan- out already there — a user with a browser tab, a PWA, and the native app installed gets all three delivered independently, exactly as a user with two browsers already does today.</li></ul><h4 id="encryption" tabindex="-1">Encryption <a class="header-anchor" href="#encryption" aria-label="Permalink to &quot;Encryption&quot;">​</a></h4><p>The relay must never be able to decrypt a payload — this is the whole point of the design, not an optional hardening pass. Reuses the same <em>concept</em> RFC 0016 already implements (public-key encryption against a client-generated keypair, no shared secret ever transmitted), but not its exact wire format: Web Push&#39;s <code>aes128gcm</code> framing (RFC 8291) exists to satisfy browser <code>PushManager</code> internals, a constraint that doesn&#39;t apply here since Sovereign controls both the encrypting server and the decrypting native client. Proposed: ECDH (P-256, the same curve already in use for VAPID) to derive a shared secret with the device&#39;s public key, HKDF to derive an AES-256-GCM key, standard authenticated encryption of the JSON payload. All primitives have first-class support in Node&#39;s <code>crypto</code> module (server) and native <code>CryptoKit</code>/<code>javax.crypto</code> (client) — no exotic cross-platform crypto library dependency needed. Exact framing (nonce handling, associated data) is an implementation detail for the workstream, not re-litigated here, but must be specified in code review before this ships, given the security stakes.</p><h4 id="the-relay-push-endpoint" tabindex="-1">The relay push endpoint <a class="header-anchor" href="#the-relay-push-endpoint" aria-label="Permalink to &quot;The relay push endpoint&quot;">​</a></h4><ul><li><code>POST /v1/push</code> — accepts <code>{deviceToken, platform, encryptedPayload, instanceKey}</code>. Validates <code>instanceKey</code> against the shared platform enrollment (above), forwards to APNs (HTTP/2, JWT signed with <code>sovereignfs</code>&#39;s <code>.p8</code> key) or FCM (HTTP v1 API, <code>sovereignfs</code>&#39;s service-account credential) depending on <code>platform</code>, returns the outcome — including a distinct &quot;token invalid&quot; result so the calling instance can prune it the same way a 410 from <code>web-push</code> already prunes <code>push_subscriptions</code>.</li><li>Nothing else. No payload inspection, no logging of decrypted content (it never receives any), no persistent notification history.</li></ul><h3 id="feature-webrtc-signaling" tabindex="-1">Feature: WebRTC signaling <a class="header-anchor" href="#feature-webrtc-signaling" aria-label="Permalink to &quot;Feature: WebRTC signaling&quot;">​</a></h3><p>Design-sketched only — enough to confirm it fits the shared relay&#39;s shape and doesn&#39;t force a deployment redesign later, not enough to start building. The first planned real consumer (a decentralized chat app) is not designed here; its concrete requirements (offline delivery, group fan-out, possible TURN relay for media/data) are deferred to that work, per this RFC&#39;s &quot;Alternatives considered.&quot;</p><ul><li><strong>What it does:</strong> relays the connection-negotiation messages (SDP offer, SDP answer, ICE candidates) two peers exchange before attempting a direct WebRTC connection. It never sees the peer-to-peer traffic itself once a direct connection succeeds — only the short-lived handshake metadata.</li><li><strong>Why it needs a relay at all:</strong> two devices behind NATs generally can&#39;t reach each other&#39;s signaling channel directly without a third, reliably-reachable party to exchange that handshake through first — the same shape of &quot;someone has to be reachable&quot; problem push has, minus the app-identity credential binding.</li><li><strong>Rough contract sketch (not final):</strong> short-TTL session records, keyed by an ephemeral session/room identifier the two participating instances already agree on out-of-band (mechanism TBD by whatever feature consumes this first). Likely <code>POST</code>/long-poll or a short-lived WebSocket per session for offer/answer/ICE exchange; the session record expires and is discarded shortly after both sides have exchanged what they need, or after a timeout if one side never shows up.</li><li><strong>Explicitly not decided here:</strong> exact endpoint shapes, session addressing scheme, whether a WebSocket or HTTP long-poll is used, TURN/relay-of-last-resort for peers that can&#39;t connect directly at all, and anything specific to a chat use case (message storage, offline delivery, group fan-out). These belong to the feature that actually needs them.</li></ul><h3 id="deployment-topology" tabindex="-1">Deployment topology <a class="header-anchor" href="#deployment-topology" aria-label="Permalink to &quot;Deployment topology&quot;">​</a></h3><p>This is the section that didn&#39;t exist in this RFC&#39;s original push-only draft, and the reason <code>apps/relay</code> doesn&#39;t yet have a <code>Dockerfile</code> or a <code>docker-compose.yml</code> entry as of this RFC&#39;s Draft status.</p><ul><li><strong>Not part of the default self-hosted stack.</strong> <code>docker-compose.yml</code> and <code>docker-compose.prod.yml</code> model what <em>every</em> self-hosted operator runs — <code>auth</code> and <code>runtime</code>. The relay is different: one <code>sovereignfs</code>-operated instance serves every self-hosted instance by default, the same way one <code>push.bitwarden.com</code> serves every self-hosted Bitwarden install. Adding it to those compose files would incorrectly imply every operator should run their own — most operators never need to, and doing so without also taking the two steps below accomplishes nothing (see &quot;Operator opt-out paths&quot;).</li><li><strong>Own Dockerfile, published image.</strong> <code>apps/relay/Dockerfile</code> follows <code>apps/auth/Dockerfile</code>&#39;s standalone-Next.js pattern. The image is added to <code>.github/workflows/publish-images.yml</code>&#39;s GHCR matrix (<code>ghcr.io/sovereignfs/sovereign-relay</code>), tagged the same way as <code>sovereign-runtime</code>/<code>sovereign-auth</code> on every <code>v*.*.*</code> release. This matters for two distinct consumers: <code>sovereignfs</code> itself, deploying its own default relay instance, and any operator taking the self-host escape hatch (below) — neither should have to build the image from source.</li><li><strong>Instance-side configuration, not compile-time.</strong> Each self-hosted instance gets an admin-configurable relay URL (Console setting, backed by an env var default) — never hard-coded. It ships with a default pointing at <code>sovereignfs</code>&#39;s relay (<code>relay.sovereign.openfs.io</code>), can be overridden to a different relay, and can be <strong>fully disabled</strong> with a single opt-out (an explicit &quot;off&quot; value, distinct from an unset/default value) — an instance with the relay disabled simply never registers push device tokens or signaling sessions; Web Push and every other feature are entirely unaffected.</li><li><strong>Deployed via the existing operator-facing infra playbook, not new tooling.</strong> Both <code>sovereign-infra</code> (public, forkable template) and <code>openfs-infra</code> (private, <code>sovereignfs</code>&#39;s own production infra) already document a generic &quot;Adding a New App&quot; flow: a per-app <code>docker-compose.yml</code><ul><li>Caddy vhost + encrypted <code>.env</code>, deployed independently of the <code>sovereign</code> app itself (whose compose is special-cased, fetched from this monorepo&#39;s releases). <code>apps/relay</code> is deployed as exactly that kind of app in both repos:</li></ul><ul><li><code>openfs-infra</code> gets an <code>apps/relay/</code> entry for <code>sovereignfs</code>&#39;s actual production relay at <code>relay.sovereign.openfs.io</code> (port <code>4002</code>, already reserved in that repo&#39;s port registry).</li><li><code>sovereign-infra</code>&#39;s template gains an <strong>optional</strong> step (a single prompt in <code>configure.sh</code>, off by default) for an operator who wants to self-host their own relay instance as part of the escape hatch below.</li></ul></li><li><strong>Operator opt-out paths — two, with different requirements:</strong><ul><li><strong>Disable the feature entirely.</strong> One <code>.env</code>/Console toggle. No relay dependency, no credentials, no separate deployment. Push notifications (and, later, signaling-dependent features) simply don&#39;t work for that instance; everything else is unaffected.</li><li><strong>Full self-host, no <code>sovereignfs</code> dependency.</strong> For push, this requires <em>three</em> things together, not any one alone: (1) a separately signed app build under the operator&#39;s own Apple Developer account / Firebase project — required because APNs/FCM tokens are permanently bound to whichever app identity generated them, so there is no way to point the standard App Store build at different credentials; (2) the operator&#39;s own APNs <code>.p8</code> key and FCM service-account credential, obtainable only because they now own that app identity; (3) their own deployed <code>apps/relay</code> instance, configured with those credentials, with their instance&#39;s relay URL pointed at it. <strong>For WebRTC signaling, only the third step applies</strong> — self-hosting the relay is sufficient on its own, since signaling has no app-identity credential binding the way push does. This asymmetry is worth remembering when documenting the escape hatch: it&#39;s a real, low-effort option for signaling and a deliberately higher-effort one for push.</li></ul></li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><p>See <a href="./../research/0010-native-mobile-push-notifications.html#options-considered">Research 0010</a> for the full option comparison (A–E) that preceded this RFC&#39;s push design. Summary of what was rejected and why:</p><ul><li><strong>Unencrypted full-payload relay</strong> — simpler, but means every self-hosted instance&#39;s notification content transits a <code>sovereignfs</code>-operated server. Rejected once the Nextcloud precedent showed the encrypted version costs little extra and has no meaningful reliability downside.</li><li><strong>Silent-wake-then-fetch</strong> (rather than a directly encrypted payload) — the originally proposed design before precedent research; depends on iOS/Android&#39;s unpredictable background-execution budget for the content-fetch step, a real reliability risk. Superseded by delivering the encrypted payload directly in one push, per Nextcloud&#39;s design.</li><li><strong>Operator-supplied credentials via Console, no relay</strong> — investigated in depth (Research 0010): structurally impossible for iOS (Apple&#39;s Bundle ID / Developer-account binding), partially possible but asymmetric for Android (a per-operator Firebase project), and doesn&#39;t reduce the design space since iOS would still need a central mechanism regardless. Not pursued as the primary path; the &quot;build your own app&quot; escape hatch remains available for operators who want it.</li><li><strong>A third-party push SaaS (OneSignal, Pushwoosh, Airship, etc.) instead of building the relay in-house</strong> — confirmed these platforms still require <code>sovereignfs</code>&#39;s own APNs/Firebase credentials to be supplied to them; they don&#39;t remove the credential-ownership constraint, and adding one introduces a new external company with visibility into device tokens without buying back any capability. Rejected.</li><li><strong>Designing WebRTC signaling&#39;s full contract (and any chat-specific capability — offline mailbox, group fan-out, TURN) now, alongside push</strong> — deliberately not done. The only concrete near-term need for signaling is a not-yet-designed decentralized chat app; speculatively designing its storage/fan-out/TURN requirements today risks building the wrong thing. This RFC only commits to the parts that affect the shared relay&#39;s deployment shape (which, per the design sketch above, are minimal): a short-TTL, content-blind rendezvous endpoint. Everything chat-specific is explicitly deferred to when that work starts.</li><li><strong>Bundling the relay into <code>auth</code>/<code>runtime</code>&#39;s default compose stack, with a local-first-then-central-fallback hop for every feature</strong> — considered and rejected for push specifically: there is no locality benefit to a local relay hop for push (the destination is always Apple/Google&#39;s cloud regardless of which relay forwards the request), so a bundled, always-running local relay would sit idle for the large majority of instances that never obtain their own push credentials, at real resource cost with no functional benefit. The same local-first pattern may be worth revisiting specifically for WebRTC signaling or a future same-network delivery optimization (see Research 0010&#39;s &quot;Home Assistant local push&quot; note), where locality genuinely helps — but that is a per-feature decision, not a property of the shared relay&#39;s default deployment.</li></ul><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ul><li>Exact enrollment/key-rotation design for relay authentication (see &quot;Shared relay platform&quot; above) — deferred to implementation, not a blocker to accepting this RFC&#39;s overall shape.</li><li>Whether to also build the Android operator-supplied-Firebase-project path as a second push escape hatch (Research 0010 leans toward deferring this indefinitely — it only covers one platform).</li><li>Home Assistant&#39;s local-network WebSocket fallback (bypass the relay entirely when phone and instance share a network) is a plausible future latency improvement for push, explicitly out of scope for v1.</li><li>Rate-limit thresholds and abuse-response behavior for the relay (block an instance, notify its admin, or both) — needs a concrete policy before the relay goes live, not before this RFC is accepted.</li><li>WebRTC signaling&#39;s actual endpoint/session design, and whether it needs a TURN-capable relay-of-last-resort for peers that can&#39;t connect directly — both deferred to whichever feature (expected: the future decentralized chat app) first needs signaling for real. Note that a TURN component, if ever needed, is very likely <strong>not</strong> something that fits inside <code>apps/relay</code>&#39;s Next.js process — TURN relays raw UDP/TCP media/data and needs a different runtime (e.g. <code>coturn</code>) — so it would run as a sibling process on the same relay infrastructure, not a route inside this app.</li></ul><h2 id="adoption-path" tabindex="-1">Adoption path <a class="header-anchor" href="#adoption-path" aria-label="Permalink to &quot;Adoption path&quot;">​</a></h2><p>Documentation-first now. The push feature is sequenced by <a href="./../workstreams/0005-native-push-relay.html">workstream 0005</a> across two repositories: this monorepo (<code>apps/relay</code> service, <code>packages/db</code> schema, <code>runtime</code> registration API and fan-out extension — epic task 4.7) and <code>sovereign-mobile</code> (client registration, encryption, iOS Notification Service Extension — epic task 20.5, rescoped from its current unscoped form the same way task 20.3 was rescoped for the device bridge). Workstream 0005 also covers the shared deployment topology (<code>apps/relay</code>&#39;s <code>Dockerfile</code>, its <code>publish-images.yml</code> entry, and the operator-facing infra playbook in <code>sovereign-infra</code>/<code>openfs-infra</code>), since push is the feature that needs it first — the relay app is <em>built</em> generalized so a later WebRTC-signaling workstream can add a second feature to the same deployable without redoing that work, but no signaling implementation is sequenced by this RFC or workstream 0005.</p><p>No semver-breaking change to any published package; <code>@sovereignfs/sdk</code> is unaffected since this is a server + relay + shell-native feature, not a plugin-facing SDK surface — plugins keep calling <code>sdk.notifications.send()</code> exactly as they do today, unaware of which channel(s) actually deliver it.</p><h2 id="addendum-desktop-native-push-macos-apns-windows-wns-linux-out-of-scope" tabindex="-1">Addendum: Desktop native push (macOS APNs, Windows WNS; Linux out of scope) <a class="header-anchor" href="#addendum-desktop-native-push-macos-apns-windows-wns-linux-out-of-scope" aria-label="Permalink to &quot;Addendum: Desktop native push (macOS APNs, Windows WNS; Linux out of scope)&quot;">​</a></h2><p><strong>Status:</strong> Implemented — <a href="./../workstreams/0010-desktop-push-relay.html">workstream 0010</a>&#39;s 3 legs are all merged (epic tasks 4.8 and 17.11). Extends the already-Implemented mobile leg (epic task 4.7 / workstream 0005) to <code>sovereign-desktop</code>, reusing the same schema, relay, and fan-out machinery rather than building a parallel system. Real gaps remain (revocation, real-credential/real-hardware verification, a macOS Notification Service Extension equivalent) — see workstream 0010&#39;s own &quot;Definition of done&quot; for the full, honest list.</p><h3 id="motivation-1" tabindex="-1">Motivation <a class="header-anchor" href="#motivation-1" aria-label="Permalink to &quot;Motivation&quot;">​</a></h3><p><code>sovereign-desktop</code> epic task 17.2 already ships local, foreground-triggered OS notifications (<code>notifications.native</code>, RFC 0083) — but, like <code>sovereign-mobile</code> before this RFC, has no path to notify a user once the app is fully quit. Unlike mobile, a desktop process isn&#39;t OS-suspended by default and a tray-resident app could in principle stay connected — but users do quit desktop apps, and when they do, only real OS-level push closes the gap, the same way it did for mobile.</p><h3 id="current-state-desktop-specific" tabindex="-1">Current state (desktop-specific) <a class="header-anchor" href="#current-state-desktop-specific" aria-label="Permalink to &quot;Current state (desktop-specific)&quot;">​</a></h3><p><code>sovereign-desktop</code> is a Tauri 2 app, identifier <code>fs.sovereign.desktop</code>, macOS-first, shipping as an unpackaged <code>.dmg</code>/<code>.exe</code>/<code>.AppImage</code> — no MSIX, no Mac App Store (that&#39;s the still-parked epic task 17.6). Its device bridge (RFC 0083, <code>src-tauri/src/bridge.rs</code>) already implements <code>notifications.native</code> via <code>tauri-plugin-notification</code>&#39;s <code>NotificationExt</code> — foreground/locally-triggered only, unrelated to this addendum&#39;s server-initiated delivery except that the native app reuses the same display path once a push is decrypted, mirroring how <code>sovereign-mobile</code> leg 4 reused its own <code>notifications.native</code> display path.</p><h3 id="proposed-design-1" tabindex="-1">Proposed design <a class="header-anchor" href="#proposed-design-1" aria-label="Permalink to &quot;Proposed design&quot;">​</a></h3><p><strong>Schema.</strong> <code>push_device_tokens.platform</code> gains <code>&#39;macos&#39;</code> and <code>&#39;windows&#39;</code> alongside the existing <code>&#39;ios&#39;</code>/<code>&#39;android&#39;</code>. The column is untyped <code>text</code> in both dialects — no migration needed. TypeScript-level validation widens in the registration API (<code>runtime/app/api/account/push-device-token/route.ts</code>) and the relay&#39;s push route.</p><p><strong>macOS uses APNs</strong> — the same service as iOS, under the same Apple Developer Team, but a distinct app identity (<code>fs.sovereign.desktop</code> vs. <code>fs.sovereign.mobile</code>) and therefore a distinct <code>apns-topic</code>. The relay&#39;s <code>apnsConfig()</code>/<code>sendApnsPush()</code> (<code>apps/relay/src/apns.ts</code>,<code>config.ts</code>) generalize to take an explicit topic per call instead of reading one fixed <code>config.bundleId</code> internally; a new <code>APNS_BUNDLE_ID_MACOS</code> env var is additive alongside the existing <code>APNS_BUNDLE_ID</code> (which keeps meaning iOS, unchanged). The shared JWT credential (<code>APNS_KEY</code>/<code>APNS_KEY_ID</code>/<code>APNS_TEAM_ID</code>) still gates whether APNs works at all; a platform-specific bundle-id var being unset gates only that platform, returning the same <code>platform_not_configured</code> the push route already returns for FCM.</p><p><strong>macOS decrypt-and-display — proposed to ship without a Notification Service Extension equivalent in v1.</strong> iOS&#39;s NSE exists because Xcode projects have first-class tooling (this RFC&#39;s mobile leg used the <code>xcodeproj</code> gem) for adding an extension target and an &quot;Embed Foundation Extensions&quot; build phase. Tauri&#39;s build output is a plain <code>.app</code> bundle produced by <code>tauri-bundler</code>, with no Xcode-project equivalent — embedding a macOS <code>.appex</code> (the same <code>UNNotificationServiceExtension</code> mechanism exists on macOS 10.14+, per Apple&#39;s docs) would mean new, unprecedented build tooling: a custom <code>tauri.conf.json</code> bundle hook that builds a second binary plus its own <code>Info.plist</code>/entitlements and copies it into the produced <code>.app</code>&#39;s <code>Contents/PlugIns/</code> post-build. Proposed instead: deliver a generic placeholder banner (mirroring the <code>aps.alert</code> title-space placeholder <code>sendApnsPush</code> already sends for the mutable-content path) while the app is closed; the app decrypts and shows real content once opened, reusing <code>fanOutPushToUser</code>&#39;s already-encrypted payload the same way a reopened mobile app&#39;s inbox would. Content still never transits the relay or Apple in plaintext either way — the only difference from iOS is a generic vs. specific banner while quit. A real NSE-equivalent is a plausible later leg, not ruled out, just not undertaken here.</p><p><strong>Windows uses WNS (Windows Notification Service)</strong> — a different protocol from APNs/FCM with no existing relay client. New <code>apps/relay/src/wns.ts</code>: OAuth2 client-credentials token fetch against <code>https://login.live.com/accesstoken.srf</code>, authenticating with a Partner Center-issued Package SID (as <code>client_id</code>) and its client secret — this identity step works for an unpackaged Win32 app via a free Partner Center app reservation, it does not require MSIX/Store publishing. The resulting bearer token (~24h validity per Microsoft&#39;s docs) is cached and proactively refreshed, mirroring <code>apnsJwt</code>&#39;s own caching shape. Sends are <strong>raw</strong> notifications only (<code>X-WNS-Type: wns/raw</code>), POSTed directly to the device&#39;s channel URI — WNS has no separate &quot;device token&quot;; the channel URI Windows generates client-side <em>is</em> the value stored in <code>push_device_tokens.device_token</code> for <code>&#39;windows&#39;</code> rows, a full HTTPS endpoint the relay calls directly rather than a host + opaque-token pair.</p><p>Raw-only is a deliberate scope decision, not an oversight: WNS&#39;s other notification type (&quot;toast&quot;) can render a system banner even while the app is fully quit, but only because Windows itself renders the banner from plaintext XML in the push body — there is no app code running on a quit, unpackaged app to decrypt anything first. That directly conflicts with this RFC&#39;s non-negotiable content-blind guarantee, so it&#39;s rejected (see &quot;Alternatives considered&quot;). The practical consequence: Windows push only reaches a <strong>running</strong> app (tray-resident is sufficient — it does not need to be foregrounded), and a fully-quit Windows app receives nothing, the same outcome as the Linux gap below for a different underlying reason.</p><p>Config: <code>WNS_PACKAGE_SID</code>, <code>WNS_CLIENT_SECRET</code>, gated by a <code>wnsConfigured()</code> check with the same &quot;structurally complete, environment-gated&quot; posture <code>apnsConfigured()</code>/<code>fcmConfigured()</code> already established — real credentials require a Partner Center registration unavailable in this environment.</p><p><strong>Push route dispatch</strong> (<code>apps/relay/app/v1/push/route.ts</code>) widens: <code>&#39;ios&#39;</code>/<code>&#39;macos&#39;</code> → APNs (topic selected per platform), <code>&#39;android&#39;</code> → FCM, <code>&#39;windows&#39;</code> → WNS.</p><p><strong><code>runtime/src/push.ts</code>&#39;s fan-out needs no change.</strong> <code>fanOutPushToUser</code> already forwards <code>token.platform</code> to the relay opaquely, with no branching on its value — confirmed by reading the current implementation before writing this addendum, not assumed from the mobile leg&#39;s shape.</p><p><strong>Linux is permanently out of scope for OS-level closed-app push</strong> — no Linux desktop push primitive exists, packaged or not (unlike Windows, there isn&#39;t even a raw-only fallback). <code>sovereign-desktop</code> continues to offer only foreground/loaded-instance notifications there, exactly as it does today. This is a documented platform gap, not a deferred task — nothing in this addendum&#39;s adoption path attempts it. (UnifiedPush, a self-hostable open push protocol, is a plausible future answer to this specific gap and fits this project&#39;s self-hosted ethos well, but is a materially bigger, open-ended question that belongs in its own <code>docs/research/</code> doc if ever picked up — not scoped here.)</p><p><strong>Desktop client</strong> (new epic task 17.11, tracked in <a href="./../epics/desktop.html">docs/epics/desktop.md</a>): on-device P-256 keypair generated in Rust (<code>p256</code>/<code>aes-gcm</code>/<code>hkdf</code> crates), producing the exact same 65-byte SEC1/X9.63 public-key point and the same ECDH + HKDF-SHA256 + AES-256-GCM wire format this RFC already specifies — the relay and <code>runtime/src/push-encryption.ts</code> need zero changes to support a third client language. The private key is persisted via each OS&#39;s native credential store rather than anything Rust-portable: macOS Keychain via the <code>security-framework</code> crate (mirroring <code>PushKeychain.swift</code>&#39;s approach from the mobile leg), Windows Credential Manager via the <code>windows</code> crate (mirroring <code>PushKeystore.java</code>&#39;s &quot;store both public and private key at generation time&quot; discipline, since deriving a public key back out of an opaque stored private key isn&#39;t portably possible there either). Registration happens entirely in native Rust — not the bundled onboarding page&#39;s JS, and not routed through <code>bridge.json</code>&#39;s one narrow remote grant — reading the active instance URL from the same <code>tauri-plugin-store</code><code>instances.json</code> <code>store.ts</code> already writes and the session cookie via Tauri&#39;s webview cookie API, then <code>POST</code>ing to <code>/api/account/push-device-token</code> directly. This mirrors <code>sovereign-mobile</code> leg 4&#39;s &quot;entirely native, zero new bridge capability&quot; decision for the identical reasons: RFC 0083 §7 (<code>secureStorage</code>-shaped capabilities must never be plugin-facing) and this repo&#39;s own hard rule against widening <code>bridge.json</code>&#39;s remote grant beyond <code>allow-bridge-invoke</code> both apply here without modification.</p><p>Two genuinely open integration points, neither blocking this addendum&#39;s acceptance but both real enough to name rather than hand-wave:</p><ul><li><strong>macOS device-token registration</strong> needs <code>NSApplication.registerForRemoteNotifications()</code> plus the <code>NSApplicationDelegate</code> callbacks (<code>didRegisterForRemoteNotificationsWithDeviceToken:</code> / <code>didFailToRegisterForRemoteNotificationsWithError:</code>). These are <code>NSApplicationDelegate</code>-only methods — Tauri (via the <code>tao</code> windowing crate it&#39;s built on) does not surface them as a Tauri-level event, and <code>tao</code> already owns the application delegate for its own window management. The implementation leg&#39;s first task is a spike: adding these selectors to <code>tao</code>&#39;s existing Objective-C delegate class at runtime via the Objective-C runtime (<code>objc2</code>, already a dependency here for Touch ID in epic task 17.10), not assumed solved by this addendum.</li><li><strong>Windows device-channel registration</strong> needs <code>Windows.Networking.PushNotifications.PushNotificationChannelManager</code> (via the <code>windows</code> crate) to obtain a channel URI, which for an unpackaged app requires associating the process with the Partner Center-issued identity (Package SID) at runtime — the exact current API for that association on an unpackaged Win32 app needs verification during implementation. Real verification is blocked on both a Windows machine and real Partner Center credentials, the same posture already documented for epic task 17.10&#39;s Windows Hello code (<code>src/biometrics/windows.rs</code>): type-checked via cross-compile, never built or run for real here.</li></ul><h3 id="security-considerations" tabindex="-1">Security considerations <a class="header-anchor" href="#security-considerations" aria-label="Permalink to &quot;Security considerations&quot;">​</a></h3><p>The end-to-end encryption guarantee is unchanged and unweakened by any of the above — the relay never receives plaintext regardless of platform. macOS&#39;s placeholder-banner tradeoff and Windows&#39;s running-app-only tradeoff both reduce <em>availability</em> while the app is quit, never <em>confidentiality</em>. The Windows raw/toast decision specifically exists to keep it that way — see &quot;Alternatives considered.&quot;</p><h3 id="alternatives-considered-1" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered-1" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h3><ul><li><strong>Windows toast notifications with plaintext payloads</strong> — would achieve real closed-app banners on Windows, the same outcome iOS/Android get. Rejected: it requires notification content to reach WNS (and therefore Microsoft) unencrypted, directly conflicting with this RFC&#39;s central design goal. Not pursued even as an opt-in mode, since a per-platform exception to the content-blind guarantee would be a confusing, easy-to- misconfigure promise to make to self-hosted operators.</li><li><strong>Building a macOS Notification Service Extension equivalent now</strong> — deferred rather than rejected. No existing Tauri build tooling supports it; the investment (custom bundle-hook tooling, a second signed binary) is real and separable from the rest of this addendum&#39;s scope.</li><li><strong>UnifiedPush for Linux</strong> — a legitimate, self-hosted-friendly answer to the Linux gap, explicitly not scoped here; too open-ended for an addendum, would need its own research doc first per this repo&#39;s own &quot;research precedes RFCs&quot; convention.</li></ul><h3 id="open-questions-1" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions-1" aria-label="Permalink to &quot;Open questions&quot;">​</a></h3><ul><li>The exact Tauri/<code>tao</code>/<code>objc2</code> mechanism for receiving <code>didRegisterForRemoteNotificationsWithDeviceToken:</code> — the desktop leg&#39;s first task, not resolved here.</li><li>The exact unpackaged-app identity-association API for <code>PushNotificationChannelManager</code> on Windows — same posture.</li><li>Whether a later leg should build a real macOS NSE equivalent once the rest of this ships.</li><li>Real Partner Center / Apple Developer Team credential acquisition for the desktop app&#39;s own APNs bundle ID and Windows Package SID — operational, not a design blocker, same category as the existing &quot;real Apple/Firebase credentials&quot; gap already documented for the mobile leg.</li></ul><h3 id="adoption-path-1" tabindex="-1">Adoption path <a class="header-anchor" href="#adoption-path-1" aria-label="Permalink to &quot;Adoption path&quot;">​</a></h3><p>Sequenced by a new workstream (<code>docs/workstreams/</code>) covering both repositories: this monorepo (schema/registration-API widening, relay APNs generalization, new <code>wns.ts</code> client — new epic task 4.8) and <code>sovereign-desktop</code> (native macOS/Windows registration, on-device crypto, decrypt-and-display — new epic task 17.11). Both tasks ship environment-gated, same as the mobile leg: real delivery is unverifiable without real Apple/Microsoft credentials and, for Windows, a real Windows machine.</p><h2 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Date</th><th>Change</th></tr></thead><tbody><tr><td>0.1</td><td>August 2026</td><td>Initial draft (push notifications only)</td></tr><tr><td>0.2</td><td>August 2026</td><td>Renamed <code>apps/push-relay</code> → <code>apps/relay</code>; broadened to a shared &quot;Sovereign Relay&quot; platform with a design-sketched WebRTC signaling feature; added &quot;Deployment topology&quot;</td></tr><tr><td>0.3</td><td>August 2026</td><td>Added &quot;Desktop native push&quot; addendum — macOS APNs, Windows WNS (raw-only, encrypted), Linux explicitly out of scope</td></tr></tbody></table>`,76)])])}const g=t(i,[["render",s]]);export{u as __pageData,g as default};
